const b = $json.body ?? $json;
const missing = ['outage_id', 'feeder_id'].filter((k) => b[k] == null || b[k] === '');
if (missing.length) throw new Error('Outage event missing fields: ' + missing.join(', '));
return {
  json: {
    business_key: String(b.outage_id),
    outage_id: String(b.outage_id),
    feeder_id: String(b.feeder_id),
    substation_id: String(b.substation_id ?? ''),
    operated_device_id: String(b.operated_device_id ?? ''),
    started_at: b.started_at ?? null,
    field_notes: String(b.field_notes ?? '').slice(0, 2000),
  },
};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "plan_type": {
      "type": "string",
      "enum": [
        "restoration_plan",
        "already_restored",
        "hold_for_operator"
      ],
      "description": "What the agent is proposing."
    },
    "faulted_section_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "Section the fault is localized to, from the topology."
    },
    "localization_evidence": {
      "type": "string",
      "description": "Which meters went dark and which kept power, one or two sentences."
    },
    "switching_steps": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "step": {
            "type": "integer",
            "description": "Step number, from 1."
          },
          "device_id": {
            "type": "string",
            "description": "Device to operate, from the topology."
          },
          "from_state": {
            "type": "string",
            "enum": [
              "open",
              "closed"
            ],
            "description": "State the device is in before this step."
          },
          "to_state": {
            "type": "string",
            "enum": [
              "open",
              "closed"
            ],
            "description": "State after this step."
          },
          "purpose": {
            "type": "string",
            "enum": [
              "isolate",
              "restore",
              "backfeed"
            ],
            "description": "Why this step."
          }
        },
        "required": [
          "step",
          "device_id",
          "from_state",
          "to_state",
          "purpose"
        ],
        "additionalProperties": false
      },
      "description": "Ordered switching steps for the operator to execute."
    },
    "sections_to_restore": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Sections that will have power after the plan."
    },
    "load_flow_study_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "Study id for any backfeed step, or null."
    },
    "customers_affected": {
      "type": "integer",
      "description": "Distinct premises whose latest meter event is a last gasp."
    },
    "crew_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "Crew to dispatch, from the crew tool."
    },
    "crew_task": {
      "type": "string",
      "description": "What the crew should do on arrival, one or two sentences."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "plan_type",
    "faulted_section_id",
    "localization_evidence",
    "switching_steps",
    "sections_to_restore",
    "load_flow_study_id",
    "customers_affected",
    "crew_id",
    "crew_task",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Outage response agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize outage event'); // one(): defined by guardPreamble; survives a lost item link
const snap = $json; // fresh ADMS topology, hazards, tags and AMI events for the outage's feeder
const t = out?.plan_type;
const noop = t === 'already_restored';
const devices = new Map((snap.devices ?? []).map((d) => [d.device_id, d]));
const sections = new Map((snap.sections ?? []).map((s) => [s.section_id, s]));
const unsafe = (id) => {
  const s = sections.get(id);
  if (!s) return 'unknown section';
  if ((s.open_hazards ?? []).length) return 'open hazard ' + s.open_hazards.join(', ');
  if ((s.tags ?? []).length) return 'tag ' + s.tags.join(', ');
  if (id === out?.faulted_section_id) return 'faulted section';
  return '';
};

// Customers affected, from meter data: distinct premises whose latest event is a last gasp.
const latest = new Map();
for (const e of [...(snap.meter_events ?? [])].sort((a, b) => String(a.at).localeCompare(String(b.at)))) latest.set(e.premise_id ?? e.meter_id, e.event);
const customersAffected = [...latest.values()].filter((ev) => ev === 'last_gasp').length;

if (!(cfg.active_outage_statuses ?? []).includes(snap.status)) reasons.push('outage ' + req.outage_id + ' is ' + snap.status + ' in the OMS');
if (t === 'hold_for_operator') reasons.push('agent asks the operator to plan this one');
if (out && Math.abs(Number(out.customers_affected) - customersAffected) > cfg.customers_affected_tolerance) reasons.push('agent counted ' + out.customers_affected + ' customers affected, meter data shows ' + customersAffected);
if (noop && customersAffected > 0) reasons.push('agent says restored but ' + customersAffected + ' premises are still dark');

// Hazards named in untrusted field notes that the network record does not carry go to a person.
const TERMS = ["wire down","wires down","line down","lines down","downed","sparking","arcing","fire","smoke","burning","explosion","pole down","pole broken","tree on line","tree on the line","shock","injur","trapped","public at scene"];
const noteHits = TERMS.filter((w) => req.field_notes.toLowerCase().includes(w));
if (noteHits.length) reasons.push('SAFETY: field notes mention ' + noteHits.join(', ') + '. The operator reviews before any plan');

const steps = out?.switching_steps ?? [];
if (t === 'restoration_plan') {
  if (!out.faulted_section_id || !sections.has(out.faulted_section_id)) reasons.push('faulted section ' + out?.faulted_section_id + ' is not in the network model');
  if (!steps.length) reasons.push('restoration plan has no switching steps');
  if (steps.length > cfg.max_switching_steps) reasons.push(steps.length + ' switching steps, over the limit of ' + cfg.max_switching_steps);
  if (!out.crew_id) reasons.push('no crew named for dispatch');
  if (steps.some((s) => s.purpose === 'backfeed') && !out.load_flow_study_id) reasons.push('backfeed step without a load-flow study');

  // Walk the plan against the fresh network state: every device exists, is in the stated
  // state, is untagged, and no step energizes a faulted, hazardous or tagged section.
  const state = new Map((snap.devices ?? []).map((d) => [d.device_id, d.state]));
  const energized = () => {
    const live = new Set((snap.sections ?? []).filter((s) => s.is_source).map((s) => s.section_id));
    let grew = true;
    while (grew) {
      grew = false;
      for (const d of snap.devices ?? []) {
        if (state.get(d.device_id) !== 'closed') continue;
        const [a, b] = d.sections ?? [];
        if (live.has(a) && b && !live.has(b)) { live.add(b); grew = true; }
        if (live.has(b) && a && !live.has(a)) { live.add(a); grew = true; }
      }
    }
    return live;
  };
  let live = energized();
  [...steps].sort((a, b) => a.step - b.step).forEach((s) => {
    const d = devices.get(s.device_id);
    if (!d) { reasons.push('step ' + s.step + ': device ' + s.device_id + ' is not in the network model'); return; }
    if (state.get(s.device_id) !== s.from_state) reasons.push('step ' + s.step + ': ' + s.device_id + ' is ' + state.get(s.device_id) + ', plan says ' + s.from_state);
    if ((d.tags ?? []).length) reasons.push('step ' + s.step + ': ' + s.device_id + ' carries tag ' + d.tags.join(', '));
    state.set(s.device_id, s.to_state);
    const now = energized();
    for (const id of now) {
      if (live.has(id)) continue;
      const why = unsafe(id);
      if (why) reasons.push('SAFETY: step ' + s.step + ' (' + s.device_id + ' ' + s.to_state + ') would re-energize section ' + id + ' with ' + why);
    }
    live = now;
  });
  for (const id of out.sections_to_restore ?? []) if (!live.has(id)) reasons.push('section ' + id + ' is listed as restored but the plan does not energize it');
}

const action = {
  type: t,
  outage_id: req.outage_id,
  feeder_id: req.feeder_id,
  faulted_section_id: out?.faulted_section_id ?? null,
  switching_steps: steps,
  sections_to_restore: out?.sections_to_restore ?? [],
  load_flow_study_id: out?.load_flow_study_id ?? null,
  customers_affected: customersAffected,
  crew_id: out?.crew_id ?? null,
  crew_task: out?.crew_task ?? '',
};
const summary = 'Outage ' + req.outage_id + ' on ' + req.feeder_id + ': fault localized to *' + action.faulted_section_id + '*.\n'
  + 'Customers affected (from meter data): ' + customersAffected + '.\n'
  + 'Draft switching order, ' + steps.length + ' steps, filed as pending operator execution:\n'
  + [...steps].sort((a, b) => a.step - b.step).map((s) => s.step + '. ' + s.device_id + ' ' + s.from_state + ' to ' + s.to_state + ' (' + s.purpose + ')').join('\n') + '\n'
  + 'Dispatch crew ' + action.crew_id + ': ' + action.crew_task + '\n'
  + 'Approve creates the dispatch and files the switching order. Operators execute every step.\n' + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const order = $json.switching_order ?? {};
const filed = (order.steps ?? []).map((s) => s.device_id + ':' + s.to_state).join(',');
const want = [...planned.switching_steps].sort((a, b) => a.step - b.step).map((s) => s.device_id + ':' + s.to_state).join(',');
const ok = order.status === 'pending_operator_execution' && filed === want
  && $json.dispatch?.crew_id === planned.crew_id && ['dispatched', 'assigned'].includes($json.dispatch?.status);
const detail = 'switching order ' + order.status + ' with steps [' + filed + '], dispatch ' + $json.dispatch?.crew_id + ' ' + $json.dispatch?.status
  + '; expected pending_operator_execution with [' + want + '] and crew ' + planned.crew_id;
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize outage event'); } catch (e) {}
try { agent = one('Outage response agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'Outage ' + intake.outage_id + ' · ' + intake.feeder_id + ' · ' + (agent?.output?.plan_type ?? 'no plan') + (agent?.output?.faulted_section_id ? ' · fault in ' + agent.output.faulted_section_id : '');
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "control room",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

